   384→/// Ethereum block executor factory.
   385→#[derive(Debug, Clone, Default, Copy)]
   386→pub struct OpBlockExecutorFactory<
   387→    R = OpAlloyReceiptBuilder,
   388→    Spec = OpChainHardforks,
   389→    EvmFactory = OpEvmFactory,
   390→> {
   391→    /// Receipt builder.
   392→    receipt_builder: R,
   393→    /// Chain specification.
   394→    spec: Spec,
   395→    /// EVM factory.
   396→    evm_factory: EvmFactory,
   397→}
   398→
   399→impl<R, Spec, EvmFactory> OpBlockExecutorFactory<R, Spec, EvmFactory> {
   400→    /// Creates a new [`OpBlockExecutorFactory`] with the given spec, [`EvmFactory`], and
   401→    /// [`OpReceiptBuilder`].
   402→    pub const fn new(receipt_builder: R, spec: Spec, evm_factory: EvmFactory) -> Self {
   403→        Self { receipt_builder, spec, evm_factory }
   404→    }
   405→
   406→    /// Exposes the receipt builder.
   407→    pub const fn receipt_builder(&self) -> &R {
   408→        &self.receipt_builder
   409→    }
   410→
   411→    /// Exposes the chain specification.
   412→    pub const fn spec(&self) -> &Spec {
   413→        &self.spec
   414→    }
   415→
   416→    /// Exposes the EVM factory.
   417→    pub const fn evm_factory(&self) -> &EvmFactory {
   418→        &self.evm_factory
   419→    }
   420→}
