   507→    fn prepare_jovian_db(da_footprint_gas_scalar: u16) -> State<InMemoryDB> {
   508→        const L1_BASE_FEE: U256 = uint!(1_U256);
   509→        const L1_BLOB_BASE_FEE: U256 = uint!(2_U256);
   510→        const L1_BASE_FEE_SCALAR: u64 = 3;
   511→        const L1_BLOB_BASE_FEE_SCALAR: u64 = 4;
   512→        const L1_FEE_SCALARS: U256 = U256::from_limbs([
   513→            0,
   514→            (L1_BASE_FEE_SCALAR << (64 - BASE_FEE_SCALAR_OFFSET * 2)) | L1_BLOB_BASE_FEE_SCALAR,
   515→            0,
   516→            0,
   517→        ]);
   518→        const OPERATOR_FEE_SCALAR: u64 = 5;
   519→        const OPERATOR_FEE_CONST: u64 = 6;
   520→        const OPERATOR_FEE: U256 =
   521→            U256::from_limbs([OPERATOR_FEE_CONST, OPERATOR_FEE_SCALAR, 0, 0]);
   522→
   523→        let mut da_footprint_scalar_bytes = [0; 8];
   524→        da_footprint_scalar_bytes[0] = (da_footprint_gas_scalar >> 8) as u8;
   525→        da_footprint_scalar_bytes[1] = da_footprint_gas_scalar as u8;
   526→
   527→        let da_footprint_gas_scalar_u64: u64 = u64::from_be_bytes(da_footprint_scalar_bytes);
   528→        let da_footprint_gas_scalar_slot_value: U256 =
