   543→            )
   544→            .unwrap();
   545→        db.database
   546→            .insert_account_storage(L1_BLOCK_CONTRACT, ECOTONE_L1_FEE_SCALARS_SLOT, L1_FEE_SCALARS)
   547→            .unwrap();
   548→        db.database
   549→            .insert_account_storage(L1_BLOCK_CONTRACT, OPERATOR_FEE_SCALARS_SLOT, OPERATOR_FEE)
   550→            .unwrap();
   551→        db.database
   552→            .insert_account_storage(
