   567→    fn build_executor<'a>(
   568→        db: &'a mut State<InMemoryDB>,
   569→        receipt_builder: &'a OpAlloyReceiptBuilder,
   570→        op_chain_hardforks: &'a OpChainHardforks,
   571→        gas_limit: u64,
   572→        jovian_timestamp: u64,
   573→    ) -> OpBlockExecutor<
   574→        OpEvm<&'a mut State<InMemoryDB>, NoOpInspector>,
   575→        &'a OpAlloyReceiptBuilder,
   576→        &'a OpChainHardforks,
   577→    > {
   578→        let ctx = Context::op()
   579→            .with_db(db)
   580→            .with_chain(L1BlockInfo {
   581→                operator_fee_scalar: Some(U256::from(2)),
   582→                operator_fee_constant: Some(U256::from(50)),
   583→                ..Default::default()
   584→            })
   585→            .with_block(BlockEnv {
   586→                timestamp: U256::from(jovian_timestamp),
   587→                gas_limit,
   588→                ..Default::default()
   589→            })
   590→            .modify_cfg_chained(|cfg| cfg.spec = OpSpecId::JOVIAN);
   591→
   592→        let evm = OpEvm::new(ctx.build_op_with_inspector(NoOpInspector {}), true);
   593→
   594→        OpBlockExecutor::new(
   595→            evm,
   596→            OpBlockExecutionCtx::default(),
   597→            op_chain_hardforks,
   598→            receipt_builder,
   599→        )
   600→    }
